Write {"file_path":"D:\code\tutors-assistant\src\state\wizard-state.ts","content":"import { createContext, useContext } from "react";

export interface ContentItem {
  type: "talk" | "lab" | "note";
  title: string;
  stepCount?: number;
}

export interface UnitConfig {
  title: string;
  items: ContentItem[];
}

export interface TopicConfig {
  title: string;
  units: UnitConfig[];
}

export interface WizardState {
  courseTitle: string;
  courseDescription: string;
  credits: string;

  topics: TopicConfig[];

  currentStep: number;
  outputDirectory: string;
  generationComplete: boolean;
}

export type WizardAction =
  | { type: "SET_COURSE_DETAILS"; courseTitle: string; courseDescription: string; credits: string }
  | { type: "SET_TOPICS"; topics: TopicConfig[] }
  | { type: "NEXT_STEP" }
  | { type: "PREV_STEP" }
  | { type: "SET_COMPLETE" };

export const initialState: WizardState = {
  courseTitle: "",
  courseDescription: "",
  credits: "",
  topics: [],
  currentStep: 1,
  outputDirectory: process.cwd(),
  generationComplete: false,
};

export function wizardReducer(state: WizardState, action: WizardAction): WizardState {
  switch (action.type) {
    case "SET_COURSE_DETAILS":
      return { ...state, courseTitle: action.courseTitle, courseDescription: action.courseDescription, credits: action.credits };
    case "SET_TOPICS":
      return { ...state, topics: action.topics };
    case "NEXT_STEP":
      return { ...state, currentStep: Math.min(state.currentStep + 1, 5) };
    case "PREV_STEP":
      return { ...state, currentStep: Math.max(state.currentStep - 1, 1) };
    case "SET_COMPLETE":
      return { ...state, generationComplete: true };
    default:
      return state;
  }
}

interface WizardContextValue {
  state: WizardState;
  dispatch: React.Dispatch<WizardAction>;
}

export const WizardContext = createContext<WizardContextValue>({
  state: initialState,
  dispatch: () => {},
});

export function useWizard() {
  return useContext(WizardContext);
}
"}

