import path from "path";
import type { WizardState } from "../state/wizard-state.js";
import { slugify, padNumber } from "../utils/slugify.js";
import { createPlaceholderPng, PLACEHOLDER_PDF } from "./placeholder-image.js";
import * as t from "./templates.js";

export interface GenerationEvent {
  type: "file" | "directory";
  path: string;
  current: number;
  total: number;
}

function countFiles(state: WizardState): number {
  let count = 3; // course.md, course.png, properties.yaml
  for (const topic of state.topics) {
    count += 2; // topic.md, topic.png
    for (const unit of topic.units) {
      count += 1; // unit.md
      for (const item of unit.items) {
        switch (item.type) {
          case "talk":
            count += 3; // .md, .pdf, .png
            break;
          case "lab":
            count += 1 + (item.stepCount || 3) + 1; // objectives + steps + img/main.png
            break;
          case "note":
            count += 2; // .md, .png
            break;
        }
      }
    }
  }
  return count;
}

export async function* generateCourse(
  state: WizardState,
  outputDir: string
): AsyncGenerator<GenerationEvent> {
  const total = countFiles(state);
  let current = 0;

  const courseSlug = slugify(state.courseTitle);
  const courseDir = path.join(outputDir, courseSlug);

  fs.mkdirSync(courseDir, { recursive: true });

  const emit = (filePath: string): GenerationEvent => {
    current++;
    return { type: "file", path: filePath, current, total };
  };

  // Course root files
  const courseMdPath = path.join(courseDir, "course.md");
  fs.writeFileSync(courseMdPath, t.courseMarkdown(state.courseTitle, state.courseDescription));
  yield emit(courseMdPath);

  const coursePngPath = path.join(courseDir, "course.png");
  fs.writeFileSync(coursePngPath, createPlaceholderPng("course"));
  yield emit(coursePngPath);

  const propsPath = path.join(courseDir, "properties.yaml");
  fs.writeFileSync(propsPath, t.propertiesYaml(state.credits));
  yield emit(propsPath);

  // Topics
  for (let ti = 0; ti < state.topics.length; ti++) {
    const topic = state.topics[ti];
    const topicSlug = slugify(topic.title);
    const topicDir = path.join(courseDir, `topic-${padNumber(ti + 1)}-${topicSlug}`);
    fs.mkdirSync(topicDir, { recursive: true });

    const topicMdPath = path.join(topicDir, "topic.md");
    fs.writeFileSync(topicMdPath, t.topicMarkdown(topic.title));
    yield emit(topicMdPath);

    const topicPngPath = path.join(topicDir, "topic.png");
    fs.writeFileSync(topicPngPath, createPlaceholderPng("topic"));
    yield emit(topicPngPath);

    // Units
    for (let ui = 0; ui < topic.units.length; ui++) {
      const unit = topic.units[ui];
      const unitDir = path.join(topicDir, `unit-${ui + 1}`);
      fs.mkdirSync(unitDir, { recursive: true });

      const unitMdPath = path.join(unitDir, "unit.md");
      fs.writeFileSync(unitMdPath, t.unitMarkdown(unit.title));
      yield emit(unitMdPath);

      let talkIndex = 0;
      let labIndex = 0;
      let noteIndex = 0;

      for (const item of unit.items) {
        switch (item.type) {
          case "talk": {
            talkIndex++;
            const talkSlug = slugify(item.title);
            const talkDir = path.join(unitDir, `talk-${talkIndex}-${talkSlug}`);
            fs.mkdirSync(talkDir, { recursive: true });

            const talkMdPath = path.join(talkDir, `${talkSlug}.md`);
            fs.writeFileSync(talkMdPath, t.talkMarkdown(item.title));
            yield emit(talkMdPath);

            const talkPdfPath = path.join(talkDir, `${talkSlug}.pdf`);
            fs.writeFileSync(talkPdfPath, PLACEHOLDER_PDF);
            yield emit(talkPdfPath);

            const talkPngPath = path.join(talkDir, `${talkSlug}.png`);
            fs.writeFileSync(talkPngPath, createPlaceholderPng("talk"));
            yield emit(talkPngPath);
            break;
          }
          case "lab": {
            const letter = String.fromCharCode(97 + labIndex); // a, b, c...
            labIndex++;
            const labSlug = slugify(item.title);
            const labDir = path.join(unitDir, `book-${letter}`);
            fs.mkdirSync(labDir, { recursive: true });

            const stepCount = item.stepCount || 3;

            const objPath = path.join(labDir, `00.${labSlug}.md`);
            fs.writeFileSync(objPath, t.labObjectivesMarkdown(item.title));
            yield emit(objPath);

            for (let si = 1; si <= stepCount; si++) {
              const stepPath = path.join(labDir, `${padNumber(si)}.Step-${padNumber(si)}.md`);
              fs.writeFileSync(stepPath, t.labStepMarkdown(si));
              yield emit(stepPath);
            }

            const imgDir = path.join(labDir, "img");
            fs.mkdirSync(imgDir, { recursive: true });
            const imgPath = path.join(imgDir, "main.png");
            fs.writeFileSync(imgPath, createPlaceholderPng("lab"));
            yield emit(imgPath);
            break;
          }
          case "note": {
            noteIndex++;
            const noteDir = path.join(unitDir, `note-${noteIndex}`);
            fs.mkdirSync(noteDir, { recursive: true });

            const noteMdPath = path.join(noteDir, "note.md");
            fs.writeFileSync(noteMdPath, t.noteMarkdown(item.title));
            yield emit(noteMdPath);

            const notePngPath = path.join(noteDir, "note.png");
            fs.writeFileSync(notePngPath, createPlaceholderPng("note"));
            yield emit(notePngPath);
            break;
          }
        }
      }
    }
  }
}
"}

