    const unit: UnitConfig = {
      title: currentUnit.title || "Main",
      items: finalItems,
    };
    const updatedUnits = [...units, unit];

    if (updatedUnits.length < unitCount) {
      setUnits(updatedUnits);
      setItems([]);
      setCurrentUnit({});
      setPhase({ kind: "unit-title", unitIndex: updatedUnits.length });
    } else {
      finishTopic(updatedUnits);
    }
  };

  const finishTopic = (finalUnits: UnitConfig[]) => {
    const updatedTopics = [...state.topics];
    updatedTopics[topicIndex] = { ...topic, units: finalUnits };
    dispatch({ type: "SET_TOPICS", topics: updatedTopics });

    if (topicIndex + 1 < state.topics.length) {
      setTopicIndex(topicIndex + 1);
      setUnits([]);
      setUnitCount(0);
      setCurrentUnit({});
      setItems([]);
      setPhase({ kind: "unit-count" });
    } else {
      dispatch({ type: "NEXT_STEP" });
    }
  };

  const renderPhase = () => {
    switch (phase.kind) {
      case "unit-count":
        return (
          <NumberInput
            label="How many units"
            min={1}
            max={10}
            defaultValue={1}
            isActive={true}
            onSubmit={(n) => {
              setUnitCount(n);
              setPhase({ kind: "unit-title", unitIndex: 0 });
            }}
          />
        );

      case "unit-title":
        return (
          <LabeledInput
            label={`Unit ${phase.unitIndex + 1} title`}
            placeholder="e.g. Main Lesson"
            isActive={true}
            onSubmit={(val) => {
              setCurrentUnit({ title: val.trim() || "Main Lesson" });
              setItems([]);
              setTalkCount(0);
              setPhase({ kind: "talk-count", unitIndex: phase.unitIndex });
            }}
          />
        );

      case "talk-count":
        return (
          <NumberInput
            label="How many talks/lectures"
            min={0}
            max={10}
            defaultValue={1}
            isActive={true}
            onSubmit={(n) => {
              setTalkCount(n);
              if (n > 0) {
                setPhase({ kind: "talk-title", unitIndex: phase.unitIndex, talkIndex: 0 });
              } else {
                setPhase({ kind: "lab-count", unitIndex: phase.unitIndex });
              }
            }}
          />
        );

      case "talk-title":
        return (
          <LabeledInput
            label={`Talk ${phase.talkIndex + 1} title`}
            placeholder="e.g. Welcome Lecture"
            isActive={true}
            onSubmit={(val) => {
              const updatedItems = [...items, { type: "talk" as const, title: val.trim() || `Talk ${phase.talkIndex + 1}` }];
              setItems(updatedItems);
              if (phase.talkIndex + 1 < talkCount) {
                setPhase({ kind: "talk-title", unitIndex: phase.unitIndex, talkIndex: phase.talkIndex + 1 });
              } else {
                setPhase({ kind: "lab-count", unitIndex: phase.unitIndex });
              }
            }}
          />
        );

      case "lab-count":
        return (
          <NumberInput
            label="How many labs"
            min={0}
            max={10}
            defaultValue={0}
            isActive={true}
            onSubmit={(n) => {
              setLabCount(n);
              if (n > 0) {
                setPhase({ kind: "lab-title", unitIndex: phase.unitIndex, labIndex: 0 });
              } else {
                setPhase({ kind: "note-count", unitIndex: phase.unitIndex });
              }
            }}
          />
        );

      case "lab-title":
        return (
          <LabeledInput
            label={`Lab ${phase.labIndex + 1} title`}
            placeholder="e.g. Setup Environment"
            isActive={true}
            onSubmit={(val) => {
              setPhase({
                kind: "lab-steps",
                unitIndex: phase.unitIndex,
                labIndex: phase.labIndex,
              });
              setItems([...items, {
                type: "lab" as const,
                title: val.trim() || `Lab ${phase.labIndex + 1}`,
                stepCount: 3,
              }]);
            }}
          />
        );

      case "lab-steps":
        return (
          <NumberInput
            label={`Steps for lab ${phase.labIndex + 1}`}
            min={1}
            max={20}
            defaultValue={3}
            isActive={true}
            onSubmit={(n) => {
              const updatedItems = [...items];
              const lastLab = updatedItems[updatedItems.length - 1];
              if (lastLab) lastLab.stepCount = n;
              setItems(updatedItems);

              if (phase.labIndex + 1 < labCount) {
                setPhase({ kind: "lab-title", unitIndex: phase.unitIndex, labIndex: phase.labIndex + 1 });
              } else {
                setPhase({ kind: "note-count", unitIndex: phase.unitIndex });
              }
            }}
          />
        );

      case "note-count":
        return (
          <NumberInput
            label="How many notes"
            min={0}
            max={10}
            defaultValue={0}
            isActive={true}
            onSubmit={(n) => {
              setNoteCount(n);
              if (n > 0) {
                setPhase({ kind: "note-title", unitIndex: phase.unitIndex, noteIndex: 0 });
              } else {
                finishUnit(items);
              }
            }}
          />
        );

      case "note-title":
        return (
          <LabeledInput
            label={`Note ${phase.noteIndex + 1} title`}
            placeholder="e.g. Key Concepts"
            isActive={true}
            onSubmit={(val) => {
              const updatedItems = [...items, { type: "note" as const, title: val.trim() || `Note ${phase.noteIndex + 1}` }];
              setItems(updatedItems);
              if (phase.noteIndex + 1 < noteCount) {
                setPhase({ kind: "note-title", unitIndex: phase.unitIndex, noteIndex: phase.noteIndex + 1 });
              } else {
                finishUnit(updatedItems);
              }
            }}
          />
        );
    }
  };

  const completedTopics = state.topics.slice(0, topicIndex).filter((t) => t.units.length > 0);

  return (
    <Box flexDirection="column">
      <Text bold color="yellow">
        Content for Topic {topicIndex + 1}: {topic?.title}
      </Text>

      {completedTopics.length > 0 && (
        <Box marginTop={1} flexDirection="column">
          <Text dimColor>Completed topics:</Text>
          {completedTopics.map((t, i) => (
            <Text key={i} color="green">
              ✓ {t.title} ({t.units.length} unit{t.units.length !== 1 ? "s" : ""},{" "}
              {t.units.reduce((sum, u) => sum + u.items.length, 0)} items)
            </Text>
          ))}
        </Box>
      )}

      {units.length > 0 && (
        <Box marginTop={1} flexDirection="column">
          <Text dimColor>Units configured:</Text>
          {units.map((u, i) => (
            <Text key={i} color="green">
              ✓ {u.title} ({u.items.length} items)
            </Text>
          ))}
        </Box>
      )}

      {items.length > 0 && (
        <Box marginTop={1} flexDirection="column">
          <Text dimColor>Items added:</Text>
          {items.map((item, i) => (
            <Text key={i} color="green">
              ✓ {item.type}: {item.title}
              {item.type === "lab" ? ` (${item.stepCount} steps)` : ""}
            </Text>
          ))}
        </Box>
      )}

      <Box marginTop={1}>{renderPhase()}</Box>
    </Box>
  );
}
"}

