import path from "path";

export function StepGenerate() {
  const { state, dispatch } = useWizard();
  const [currentFile, setCurrentFile] = useState("");
  const [progress, setProgress] = useState({ current: 0, total: 0 });
  const [done, setDone] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function run() {
      try {
        const gen = generateCourse(state, state.outputDirectory);
        for await (const event of gen) {
          if (cancelled) break;
          setCurrentFile(event.path);
          setProgress({ current: event.current, total: event.total });
        }
        if (!cancelled) {
          setDone(true);
          dispatch({ type: "SET_COMPLETE" });
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : String(err));
        }
      }
    }

    run();
    return () => {
      cancelled = true;
    };
  }, []);

  const outputPath = path.join(state.outputDirectory, slugify(state.courseTitle));

  if (error) {
    return (
      <Box flexDirection="column">
        <StatusMessage variant="error">Generation failed: {error}</StatusMessage>
      </Box>
    );
  }

  if (done) {
    return (
